insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.obligatory.reasons[0].cites[1].quote', 'যে ব্যক্তি ঈমান ও প্রতিদানের আশায় রমজানের সিয়াম পালন করবে, তার পূর্বের গুনাহ ক্ষমা করে দেওয়া হবে।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[1].collection', 'muslim');
