insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.obligatory.reasons[0].cites[0].quote', 'ইসলাম পাঁচটি ভিত্তির ওপর প্রতিষ্ঠিত: এই মর্মে সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো উপাস্য নেই এবং মুহাম্মাদ আল্লাহর রাসূল, নামাজ কায়েম করা, যাকাত আদায় করা, হজ করা এবং রমজানের সিয়াম পালন করা।');
