insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'আবু উবাইদ (রা.) থেকে বর্ণিত, তিনি বলেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'আমি উমর (রা.)-এর সাথে ঈদের নামাজে উপস্থিত ছিলাম। তিনি খুতবার আগে নামাজ আদায় করলেন, অতঃপর বললেন: রাসূলুল্লাহ (সা.) এই দুই দিনের সিয়াম থেকে নিষেধ করেছেন। ঈদুল আযহার দিন তোমরা তোমাদের কুরবানির গোশত খাও, আর ঈদুল ফিতরের দিন তোমাদের সিয়াম ভঙ্গের দিন।');
