insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'দুই দিনের সিয়াম নিষিদ্ধ: ঈদুল ফিতর ও ঈদুল আযহার দিন।');
