insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'আবু কাতাদা (রা.) থেকে বর্ণিত, রাসূলুল্লাহ (সা.) বলেছেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'আমি আল্লাহর কাছে আশা করি যে, আরাফার দিনের সিয়াম পূর্ববর্তী ও পরবর্তী এক বছরের গুনাহ মোচন করবে, এবং আশুরার দিনের সিয়াম পূর্ববর্তী এক বছরের গুনাহ মোচন করবে।');
