insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[1].title', 'আরাফা ও আশুরার দিন');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'নবী (সা.)-এর কোনো এক সহধর্মিণী (রা.) থেকে বর্ণিত, তিনি বলেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'রাসূলুল্লাহ (সা.) জিলহজ মাসের প্রথম নয় দিন, আশুরার দিন এবং প্রতি মাসে তিন দিন সিয়াম পালন করতেন।');
