insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'আবদুল্লাহ ইবনু আমর ইবনুল আস (রা.) থেকে বর্ণিত, তিনি বলেন: রাসূলুল্লাহ (সা.) আমাকে বলেছেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'তোমার জন্য প্রতি মাসে তিন দিন সিয়াম পালনই যথেষ্ট; কারণ প্রতিটি নেক আমলের দশগুণ প্রতিদান রয়েছে। এভাবে তা পূর্ণ বছরের সিয়ামের সমতুল্য।');
