insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'প্রতি মাসে তিন দিন সিয়াম এবং প্রতি বছর রমজানের সিয়াম—এটিই চিরকালের সিয়াম।');
