insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'রাসূলুল্লাহ (সা.) আবু যার (রা.)-কে বলেছেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'যে ব্যক্তি প্রতি মাসে তিন দিন সিয়াম পালন করবে, তা চিরকালের সিয়ামের সমতুল্য।');
