insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'প্রতি মাসে তিন দিন সিয়াম পালন করা চিরকালের সিয়ামের সমতুল্য; আর সাদা দিনগুলো (আয়্যামুল বীদ) হলো তেরো, চৌদ্দ ও পনেরো তারিখ।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'আবু হুরাইরা (রা.) থেকে বর্ণিত, তিনি বলেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'আমার প্রিয় বন্ধু রাসূলুল্লাহ (সা.) আমাকে তিনটি বিষয়ের অসিয়ত করেছেন: প্রতি মাসে তিন দিন সিয়াম, দুই রাকআত চাশতের নামাজ এবং ঘুমানোর আগে বিতর নামাজ।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'আবুদ দারদা (রা.) থেকে বর্ণিত, তিনি বলেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'আমার প্রিয় বন্ধু রাসূলুল্লাহ (সা.) আমাকে তিনটি বিষয়ের অসিয়ত করেছেন, যেগুলো আমি কোনো অবস্থাতেই ছাড়ি না; তিনি আমাকে প্রতি মাসে তিন দিন সিয়ামের অসিয়ত করেছেন।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'রাসূলুল্লাহ (সা.) আবু যার (রা.)-কে উপদেশ দিয়েছেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'হে আবু যার! যদি তুমি মাসের কোনো দিন সিয়াম পালন করো, তবে তেরো, চৌদ্দ ও পনেরো তারিখে সিয়াম পালন করো।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
