insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[3].title', 'সাদা দিনগুলো (আয়্যামুল বীদ)');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'উসামা ইবনু যায়েদ (রা.) থেকে বর্ণিত, রাসূলুল্লাহ (সা.) বলেছেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'এই দুটি দিনে সমস্ত আমল বিশ্বজগতের রবের সামনে পেশ করা হয়; আমি চাই আমার আমল সিয়ামরত অবস্থায় পেশ করা হোক।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'আবু কাতাদা আনসারী (রা.) থেকে বর্ণিত, রাসূলুল্লাহ (সা.)-এর কাছে সোমবারের সিয়াম সম্পর্কে জিজ্ঞাসা করা হলে তিনি বলেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'এটি সেই দিন, যেদিন আমি জন্মগ্রহণ করেছি, এবং যেদিন আমার প্রতি নবুওয়াত দেওয়া হয়েছে বা ওহী নাযিল করা হয়েছে।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].hadith', '1162b');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[3].intro', 'আয়েশা (রা.) থেকে বর্ণিত, তিনি বলেন:');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[3].quote', 'নবী (সা.) সোম ও বৃহস্পতিবার সিয়াম পালনের প্রতি যত্নবান ছিলেন।');
insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].collection', 'tirmidhi');
