insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[4].cites[0].quote', 'সোম ও বৃহস্পতিবার আমলগুলো পেশ করা হয়; আমি চাই আমার আমল সিয়ামরত অবস্থায় পেশ করা হোক।');
