insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[0].cites[1].quote', 'যে ব্যক্তি রমজানের সিয়াম পালন করবে, অতঃপর শাওয়াল মাসে আরও ছয় দিন সিয়াম পালন করবে, সে যেন চিরকাল সিয়াম পালন করল।');
