insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[0].cites[2].quote', 'যে ব্যক্তি রমজান মাসের সিয়াম পালন করবে এবং এরপর শাওয়াল মাসে ছয় দিন সিয়াম পালন করবে, তা পূর্ণ বছরের সিয়ামের সমতুল্য হবে।');
