insert into i18n_bundles (locale, code, value) values ('bn', 'fasting.reason-groups.voluntary.reasons[0].cites[0].quote', 'যে ব্যক্তি ঈদুল ফিতরের পর ছয় দিন সিয়াম পালন করবে, সে পূর্ণ বছরের সিয়াম সম্পন্ন করল; কারণ যে ব্যক্তি একটি নেক আমল করবে, তার জন্য অনুরূপ দশটি নেক আমলের প্রতিদান রয়েছে।');
